// Replay in cua_repl with documented browser, batchTab, vp, batchFS and batchRoot bindings.
// Source definitions and deterministic matrix; all evaluate calls are read-only.
var browserViews=[];var frameRecords=[];var frameWanted=new Set(["balanced-1440","balanced-390","compact-1440","compact-390","editorial-1440","editorial-390","balanced-neutral-1440","balanced-neutral-390","compact-neutral-1440","compact-neutral-390","editorial-neutral-1440","editorial-neutral-390","cart-populated-1440","cart-populated-390","cart-empty-390","story-1440","story-390","story-neutral-1440","story-neutral-390","collection24-1440","collection24-390","guided-jewelry-1440","guided-jewelry-390","long-320","missing-390","many-media-768","rich-media-390","disconnected-390","rtl-390","plan-390","properties-390","app-320","cart-error-390","collection100-1440"]);
var probeBatch = () => { const root=document.documentElement; const main=document.querySelector('main');const visible=e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>0&&r.height>0&&s.visibility!=='hidden'&&s.display!=='none'&&!e.closest('details:not([open])')};const rect=e=>{const r=e.getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height}};const ids=[...document.querySelectorAll('[id]')].map(e=>e.id);const boxes=[...document.querySelectorAll('main input:not([type=hidden]),main select,main button')].filter(visible);const spills=[...document.querySelectorAll('main *')].filter(e=>visible(e)&&!e.classList.contains('sr-only')&&getComputedStyle(e).position!=='absolute').filter(e=>{const r=e.getBoundingClientRect();return r.right>innerWidth+1||r.left< -1}).map(e=>({tag:e.tagName,cls:e.className,text:e.textContent.slice(0,60),...rect(e)}));const groups=[...document.querySelectorAll('.pdp-two-zone,.editorial-purchase,.cart-layout,.purchase-band>.purchase')].map(e=>{const a=[...e.children].filter(visible);let collision=false;for(let i=0;i<a.length;i++)for(let j=i+1;j<a.length;j++){const x=a[i].getBoundingClientRect(),y=a[j].getBoundingClientRect();if(Math.min(x.right,y.right)-Math.max(x.left,y.left)>1&&Math.min(x.bottom,y.bottom)-Math.max(x.top,y.top)>1)collision=true}return {cls:e.className,collision}});return {url:location.href,fixture:root.dataset.fixture||new URL(location.href).searchParams.get('fixture'),width:innerWidth,height:innerHeight,scrollWidth:root.scrollWidth,main:main?rect(main):null,heading:[...document.querySelectorAll('h1')].map(e=>e.textContent),duplicates:ids.filter((v,i)=>ids.indexOf(v)!==i),spills:spills.slice(0,20),spillCount:spills.length,groups,controls:boxes.map(e=>({name:e.id||e.textContent.slice(0,50),...rect(e)})),purchase:document.querySelector('.product-facts')?{id:document.querySelector('.product-facts').dataset.product,variant:document.querySelector('.product-facts').dataset.variant,price:document.querySelector('.price').textContent,status:document.querySelector('.availability').textContent,addDisabled:document.querySelector('.purchase-form button').disabled}:null,media:[...document.querySelectorAll('[data-media]')].map(e=>e.dataset.media),cartLines:[...document.querySelectorAll('[data-line]')].map(e=>e.dataset.line),cardCount:document.querySelectorAll('.product-card').length,mainOrder:main?[...main.querySelectorAll('h1,h2,h3')].map(e=>e.textContent):[],stickyOwners:[...document.querySelectorAll('main *')].filter(e=>visible(e)&&['fixed','sticky'].includes(getComputedStyle(e).position)).map(e=>e.className),tokens:[root,...document.querySelectorAll('.collection,.evidence-host,.split-tension')].map(e=>({cls:e.className||'root',ink:getComputedStyle(e).getPropertyValue('--ink').trim(),type:getComputedStyle(e).fontFamily,color:getComputedStyle(e).color})),rootFont:getComputedStyle(root).fontSize,images:[...document.images].map(e=>({src:e.getAttribute('src'),complete:e.complete,naturalWidth:e.naturalWidth,loading:e.loading}))};};
var captureBatch = async(name,widths=[320,375,390,430,768,1024,1280,1440])=>{for(var w of widths){await vp.set({width:w,height:900});var url=name.startsWith('guided-')?'http://127.0.0.1:3005/guided?fixture='+name.slice(7):'http://127.0.0.1:3005/?fixture='+name;if(await batchTab.url()===url)await batchTab.reload();else await batchTab.goto(url);var obs=await batchTab.playwright.evaluate(probeBatch);for(var tries=0;obs.width!==w&&tries<4;tries++)obs=await batchTab.playwright.evaluate(probeBatch);if(obs.width!==w)throw Error('Viewport did not settle');obs.requestedFixture=name;obs.requestedWidth=w;browserViews.push(obs);var key=name+'-'+w;if(frameWanted.has(key)){await batchTab.pressKey(null,'End');await batchTab.playwright.domSnapshot();await batchTab.pressKey(null,'Home');await batchTab.playwright.domSnapshot();var jpg=await batchTab.screenshot({fullPage:true});await batchFS.writeFile(batchRoot+'/tests/evidence/frames/'+key+'.jpg',jpg);frameRecords.push({fixture:name,width:w,path:'tests/evidence/frames/'+key+'.jpg',bytes:jpg.length});}}await batchFS.writeFile(batchRoot+'/tests/evidence/browser-views.json',JSON.stringify(browserViews,null,2)+'\n');await batchFS.writeFile(batchRoot+'/tests/evidence/frames.json',JSON.stringify(frameRecords,null,2)+'\n');nodeRepl.write({fixture:name,total:browserViews.length,frames:frameRecords.length});};
var refreshFrame = async(record)=>{await vp.set({width:record.width,height:900});var url=record.fixture.startsWith('guided-')?'http://127.0.0.1:3005/guided?fixture='+record.fixture.slice(7):'http://127.0.0.1:3005/?fixture='+record.fixture;if(await batchTab.url()===url)await batchTab.reload();else await batchTab.goto(url);var state=await batchTab.playwright.evaluate(()=>({y:scrollY,h:document.documentElement.scrollHeight,v:innerHeight,w:innerWidth,loaded:[...document.images].filter(i=>i.naturalWidth>0).length,n:document.images.length}));if(state.w!==record.width)throw Error('Viewport mismatch');for(var turn=0;state.y+state.v<state.h-1&&turn<40;turn++){await batchTab.scroll([Math.min(record.width-10,150),450],'down',1);state=await batchTab.playwright.evaluate(()=>({y:scrollY,h:document.documentElement.scrollHeight,v:innerHeight,w:innerWidth,loaded:[...document.images].filter(i=>i.naturalWidth>0).length,n:document.images.length}));}if(state.loaded!==state.n)throw Error('Deferred image not loaded '+record.fixture+' '+JSON.stringify(state));await batchTab.scroll([Math.min(record.width-10,150),450],'up',40);await batchTab.playwright.domSnapshot();var jpg=await batchTab.screenshot({fullPage:true});await batchFS.writeFile(batchRoot+'/'+record.path,jpg);record.bytes=jpg.length;record.imagesLoaded=state.loaded;record.imagesTotal=state.n;};
